from os import path
from contextlib import contextmanager
from robot.utils.robottime import timestr_to_secs
from robot.api import logger

from .exception import NameIsProtected
from .validators import IsString
from .converter import to_bool, to_int

from ute_common_admin.api import AdminApi
from ute_common_admin.util import ensure_parent_dir_exists

from .interfaces import \
    AsyncInterface, \
    AutoConnectionInterface, \
    BasicProceduresInterface, \
    CertificateManagmentInterface, \
    CommissioningInterface, \
    FileCollectionInterface, \
    IPConnectivityInterface, \
    OtherProceduresInterface, \
    PMCountersInterface,  \
    RadParamsInterface, \
    SoftwareUpdateInterface, \
    TestModelInterface, \
    TiltManagement, \
    UserManagementInterface, \
    DeprecatedInterface, \
    CustomerProcedures, \
    RfDiagnosticInterface, \
    EthernetServiceOamInterface

from .delta.interface import DeltaInterface
from .fault.interface import FaultGenerationInterface
from .hw_abstract.interface import HwAbstractLayerInterface


class ute_admin(
        AsyncInterface,
        AutoConnectionInterface,
        BasicProceduresInterface,
        CertificateManagmentInterface,
        CommissioningInterface,
        DeltaInterface,
        FaultGenerationInterface,
        FileCollectionInterface,
        IPConnectivityInterface,
        HwAbstractLayerInterface,
        OtherProceduresInterface,
        PMCountersInterface,
        RadParamsInterface,
        SoftwareUpdateInterface,
        TestModelInterface,
        TiltManagement,
        UserManagementInterface,
        DeprecatedInterface,
        CustomerProcedures,
        RfDiagnosticInterface,
        EthernetServiceOamInterface):

    """
    Introduction
    ************


    Admin API wrapper for Robot Framework.
    ***WARNING!*** This library is not maintained any more.
    For testin SBTS21b onwards please use:
    ------------------------------

    ::

        https://docs.taf.nsn-rdnet.net/taf.sbts.oam.coam.admin/

    Requirements
    ********************

    * Python 2.7.x
    * pip >= 1.5.x
    * setuptools >=2.1


    Installation
    ************

    Installation for UTE test line
    ------------------------------

    ::

        pip install -U ute_admin


    Installation for NON UTE test line
    ----------------------------------

    1. Install requirements

    2. Install required UTE libraries

    ::

        pip install -U -i http://pypi.ute.inside.nsn.com:25102 ute_installer

    3. Install ute_admin

    ::

        pip install -U -i http://pypi.ute.nsn-rdnet.net:25102 ute_admin


    Installation from GIT
    ---------------------

    ::

        pip install -U git+https://wrgitlab.int.net.nokia.com/TAF/utelibs/ute_admin.git


    Proxy settings
    **************

    If you are using HTTP proxy configured in environment variables (http_proxy, https_proxy),
    please rememeber to set also no_proxy variable for localhost.

    ::

        no_proxy=localhost,127.0.0.0/8


    Sample setup configurations
    ***************************

    Default - SBTS
    -----------------------------------------

    ::

        Setup admin    bts_host=192.168.255.1    bts_port=443    use_ssl=True


    LTE (FL00)
    ---------------------------------------------------------------------------

    ::

        Setup admin    bts_host=192.168.255.1    bts_port=443    use_ssl=True


    Dist_name usage
    ***************

    From SBTS17A onwards runtime objects (xxx_R) should be used in dist_name parameter for
    keywords like: Block, Unblock, Reset Unit, Radio Reset At Layer 1

    Keywords
    ********
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def setup_admin(self,
                    bts_host="192.168.255.1",
                    bts_port=443,
                    username="Nemuadmin",
                    password="nemuuser",
                    use_ssl=True,
                    update_interval=5000,
                    admin_api_log_dir="",
                    bundle_path=None,
                    remote_host=None,
                    remote_host_username="ute",
                    remote_host_password="ute",
                    timeout=30,
                    alias="default",
                    **kwargs):
        """Setup Admin API.

        :param string bts_host: BTS IP address.
        :param integer bts_port: AdminAPI port.
        :param string username: AdminAPI username.
        :param string password: AdminAPI password.
        :param boolean use_ssl: use SSL, after PR515918 unsecure connection is not allowed.
        :param integer update_interval: The minimum updates interval in [ms].
        :param string admin_api_log_dir: AdminAPI log directory.
        :param string bundle_path: Custom bundle.js path.
        :param string remote_host: remote host ip address for SSH tunneling. None means disabled SSH tunneling.
                                    Do not use when eNB is connected to local machine!
        :param string remote_host_username: Username for remote host SSH authentication. Default is 'ute'.
        :param string remote_host_password: Password for remote host SSH authentication. Default is 'ute'.
        :param float timeout: Time to wait for Admin API setup.
        :param string alias: Name of execution context.

        WARNING::
            parameter remote_host_ssh_prompt removed in ute_admin v.4.0.0

        """
        logger.warn("""[DEPRECATION WARNING] Please be informed that for testing SBTS21B onwards taf.sbts.oam.coam.admin is recommended\n
                       Please start migration.\n
                       https://docs.taf.nsn-rdnet.net/taf.sbts.oam.coam.admin/""")
        bts_port = to_int(bts_port)
        use_ssl = to_bool(use_ssl)
        timeout = timestr_to_secs(timeout)
        debug_log = path.join(
            admin_api_log_dir, "admin_api_{}.log".format(alias))
        ensure_parent_dir_exists(debug_log)

        IsString().check(username)
        IsString().check(password)
        IsString().check(bts_host)

        api = AdminApi(
            bts_host, bts_port, username, password, use_ssl, update_interval, debug_log, bundle_path,
            remote_host, remote_host_username, remote_host_password, timeout)
        try:
            if "remote_host_ssh_prompt" in kwargs:
                api.logger.warn("parameter remote_host_ssh_prompt is deprecated for ute_admin v.4.0.0")
        except Exception:
            pass
        try:
            self.store.add(api, alias)
        except NameIsProtected:
            api.teardown()
            raise NameIsProtected(
                "Alias ({}) exists. Please remove it to reuse.".format(alias))

    def reset_admin(self, alias="default"):
        """Reset Admin API.

        :param string alias: Name of execution context.
        """
        self.store.get(alias).reset()

    def teardown_admin(self, alias="default"):
        """Teardown Admin API. Keyword will release used resources.

        :param string alias: Name of execution context.
        """
        if self.store.has_alias(alias):
            self.store.get(alias).teardown()
            self.store.remove(alias)
        else:
            logger.warn("ute_admin: Given alias not found")

    def teardown_all_aliases_for_admin(self):
        """Cleanup all ute_admin aliases."""
        self._out_of_scope()

    def _out_of_scope(self):
        for alias in self.store.aliases:
            self.teardown_admin(alias)

    @contextmanager
    def admin_context(self, **kw):
        """
            Context manager intended to simplify setting up
            and tearing down Admin by Python scripts.
            Performs setup at enter, frees resources at exit.
            Takes optional arguments passed to setup_admin.
            Examples available in the example folder
        """
        alias = kw.get('alias', 'default')
        try:
            self.setup_admin(**kw)
            yield
        finally:
            self.teardown_admin(alias=alias)
